/* ==UserStyle==
@name         Netrunner01 CDE Broica (Dark)
@namespace    local.netrunner.broica
@version      2.1.0
@description  CDE Broica dark motif for MXLinux Netrunner01 (DejaVu Serif)
@author       you
@license      MIT
==/UserStyle== */

@-moz-document url-prefix("http"), url-prefix("https") {

  /* --- Dark palette mapping
     bgBase      #2a2e38  (derived from #686f82, darkened)
     bgPanel     #3a4050  (derived from #686f82)
     bgRaised    #4a5160  (derived from #8998aa, darkened)
     textPrimary #c6b2a8  (your warm putty — now text)
     textMuted   #999999
     accentWarm  #eda870
     accentTeal  #4992a7
     accentRose  #b7878d
     hoverBg     #93abbf
  --- */

  /* Global base */
  html, body {
    background-color: #2a2e38 !important;
    color: #c6b2a8 !important;
    font-family: "DejaVu Serif", "DejaVu Serif Condensed", Georgia, serif !important;
  }

  /* Force font everywhere except code/mono contexts */
  *:not(pre):not(code):not(kbd):not(samp):not(tt):not(textarea) {
    font-family: "DejaVu Serif", "DejaVu Serif Condensed", Georgia, serif !important;
  }

  /* Kill modern rounded corners */
  * {
    border-radius: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
  }

  /* Headings */
  h1, h2, h3, h4, h5, h6 {
    color: #eda870 !important;
    font-weight: bold !important;
    border-bottom: 2px solid #4a5160 !important;
  }

  /* Links */
  a {
    color: #4992a7 !important;
    text-decoration: underline !important;
  }
  a:visited {
    color: #b7878d !important;
  }
  a:hover {
    background-color: #93abbf !important;
    color: #2a2e38 !important;
  }

  /* Stamped buttons — raised chrome look */
  button, input[type="button"], input[type="submit"],
  input[type="reset"], .btn {
    background-color: #4a5160 !important;
    color: #c6b2a8 !important;
    font-family: "DejaVu Serif", Georgia, serif !important;
    border: 2px solid !important;
    border-color: #6a7285 #1a1e28 #1a1e28 #6a7285 !important;
    padding: 2px 8px !important;
  }
  button:active, .btn:active {
    border-color: #1a1e28 #6a7285 #6a7285 #1a1e28 !important;
    background-color: #3a4050 !important;
  }

  /* Sunken inputs */
  input[type="text"], input[type="search"], input[type="email"],
  input[type="password"], input[type="url"], select {
    background-color: #1e222a !important;
    color: #c6b2a8 !important;
    font-family: "DejaVu Serif", Georgia, serif !important;
    border: 2px solid !important;
    border-color: #1a1e28 #6a7285 #6a7285 #1a1e28 !important;
    padding: 2px 4px !important;
  }

  textarea {
    background-color: #1e222a !important;
    color: #c6b2a8 !important;
    font-family: "DejaVu Sans Mono", monospace !important;
    border: 2px solid !important;
    border-color: #1a1e28 #6a7285 #6a7285 #1a1e28 !important;
  }

  /* Panels, sidebars, cards — slightly lifted from base */
  nav, aside, .sidebar, .panel, .card,
  [role="navigation"], [role="complementary"] {
    background-color: #3a4050 !important;
    border: 2px solid !important;
    border-color: #6a7285 #1a1e28 #1a1e28 #6a7285 !important;
    padding: 6px !important;
  }

  /* Selection */
  ::selection {
    background-color: #4992a7 !important;
    color: #2a2e38 !important;
  }
  ::-moz-selection {
    background-color: #4992a7 !important;
    color: #2a2e38 !important;
  }

  /* Code blocks — darker recess */
  pre, code, kbd, samp, tt {
    background-color: #1e222a !important;
    color: #eda870 !important;
    font-family: "DejaVu Sans Mono", "DejaVu Sans Mono for Powerline", monospace !important;
    border: 2px solid #1a1e28 !important;
  }
  pre code {
    border: none !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 16px !important;
    height: 16px !important;
  }
  ::-webkit-scrollbar-track {
    background: #1e222a !important;
    border: 2px solid #1a1e28 !important;
  }
  ::-webkit-scrollbar-thumb {
    background: #4a5160 !important;
    border: 2px solid !important;
    border-color: #6a7285 #1a1e28 #1a1e28 #6a7285 !important;
  }

  /* Tables */
  table, th, td {
    border: 2px solid #4a5160 !important;
    border-collapse: collapse !important;
  }
  th {
    background-color: #3a4050 !important;
  }

  /* Icon font exclusion */
  .fa, .fas, .far, .fab,
  .material-icons, .material-symbols-outlined,
  [class*="icon-"], [class^="icon-"] {
    font-family: inherit !important;
  }

}
